        "kind": "paragraph",
        "inline": [
          {
            "kind": "text",
            "value": "Unknown schema versions fail closed. The import parser limits UTF-8 input to 1 MiB, nesting to 24 levels, and the parsed value graph to 50,000 nodes. It rejects unsafe object keys, oversized keys and strings, malformed JSON, unsupported versions, and any input that fails tax-domain validation."
          }
        ]
